progress.command:
gh "pr" "view" "394" "--repo" "cv/pit" "--jq" "
def text: . // "";
def preview($n): {body: (.body | text | .[0:$n]), bodyLength: (.body | text | length)};
def passing: ((.conclusion // .state // "") | ascii_upcase) as $s
  | $s == "SUCCESS" or $s == "SKIPPED" or $s == "NEUTRAL";
{title, url, state, reviewDecision} + preview(8000) + {
 comments: ((.comments // [])[-8:] | map({author: .author.login} + preview(3000))),
 reviews: ((.reviews // [])[-8:] | map({author: .author.login, state} + preview(3000))),
 checks: ((.statusCheckRollup // []) | sort_by(if passing then 1 else 0 end) | .[0:40]
   | map({name: (.name // .context), workflow: .workflowName, status: (.status // .state),
          conclusion, url: (.detailsUrl // .targetUrl)})),
 counts: {comments: (.comments // [] | length), reviews: (.reviews // [] | length),
          checks: (.statusCheckRollup // [] | length)}}" "--json" "title,url,state,reviewDecision,body,comments,reviews,statusCheckRollup"
